SELECT 'prod' db,instrument_id,count() minutes,min(minute_time) first,max(minute_time) latest,sum(bitCount(valid_bitmap)) valid_seconds FROM crypto_market_info.order_book_minute FINAL GROUP BY instrument_id UNION ALL SELECT 'soak',0,count(),min(minute_time),max(minute_time),sum(bitCount(valid_bitmap)) FROM crypto_market_info_perp_soak.order_book_minute FINAL WHERE minute_time>='2026-09-12 18:00:00'
